The retry function's final-failure raise is untested. Write tests for first-attempt success, success after retries, and exhaustion.

def retry_call(fn, attempts=3):
    last = None
    for _ in range(attempts):
        try:
            return fn()
        except ValueError as exc:
            last = exc
    raise last

output:
import pytest
from retry import retry_call

def test_success_first_attempt():
    calls = []
    def ok():
        calls.append(1)
        return 'ok'
    assert retry_call(ok) == 'ok'
    assert len(calls) == 1

def test_success_after_retry():
    state = {'n': 0}
    def flaky():
        state['n'] += 1
        if state['n'] < 2:
            raise ValueError('again')
        return 'recovered'
    assert retry_call(flaky) == 'recovered'

def test_attempts_exhausted():
    def always():
        raise ValueError('never')
    with pytest.raises(ValueError, match='never'):
        retry_call(always, attempts=2)

