def parse_properties(text):
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        key, _, value = stripped.partition('=')
        result[key.strip()] = value.strip()
    return result

