class CircuitBreaker:
    def __init__(self, threshold=2, reset_after=1):
        self.threshold = threshold
        self.failures = 0
        self.state = 'closed'
    def record(self, success):
        if success:
            self.failures = 0
            self.state = 'closed'
        else:
            self.failures += 1
            if self.failures >= self.threshold:
                self.state = 'open'

