The except-else-finally flow in this writer is only partly tested. Write a test that triggers the finally cleanup and one that triggers the except path.

def write_report(path, content):
    handle = None
    try:
        handle = open(path, 'w')
        if content is None:
            raise ValueError('no content')
        handle.write(content)
        return 'written'
    except ValueError:
        return 'rejected'
    finally:
        if handle is not None:
            handle.close()

output:
import pytest
from report import write_report

def test_written_branch(tmp_path):
    path = tmp_path / 'r.txt'
    assert write_report(path, 'hello') == 'written'
    assert path.read_text() == 'hello'

def test_rejected_branch(tmp_path):
    path = tmp_path / 'r2.txt'
    assert write_report(path, None) == 'rejected'
    assert path.read_text() == ''

def test_finally_closed_even_on_success(tmp_path, monkeypatch):
    closed = {}
    real_open = open
    class Spy:
        def __init__(self, *a, **k):
            self._f = real_open(*a, **k)
        def write(self, data):
            return self._f.write(data)
        def close(self):
            closed['yes'] = True
            self._f.close()
    monkeypatch.setitem(__import__('builtins').__dict__, 'open', lambda *a, **k: Spy(*a, **k))
    write_report(tmp_path / 'r3.txt', 'x')
    assert closed.get('yes') is True

